  1	/**
  2	 * src/builders/persona-builder.ts
  3	 *
  4	 * Core build orchestrator for @mistralys/persona-builder.
  5	 *
  6	 * Exports three public functions:
  7	 *
  8	 *  1. buildPersona(personaYamlPath, suiteName, suiteConfig, sharedMeta,
  9	 *                  partialsMap, config, plugins, target, agentMap?)
 10	 *     — Builds a single persona for a single target. Returns a BuildResult.
 11	 *
 12	 *  2. buildSuite(suiteName, suiteConfig, config, plugins, target, agentMap?)
 13	 *     — Discovers all persona YAMLs for a suite, fires onSuiteInit, maps
 14	 *       buildPersona() over each, and returns BuildResult[].
 15	 *
 16	 *  3. build(config)
 17	 *     — Top-level entry point. Pre-scans all suites to build a cross-suite
 18	 *       agent name map, then iterates all suites × targets, calls
 19	 *       buildSuite() for each combination, and returns a BuildSummary.
 20	 *       Respects --check (no writes) and --strict (fail on warnings/errors).
 21	 */
 22	
 23	import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
 24	import { existsSync } from 'node:fs';
 25	import path from 'node:path';
 26	import yaml from 'js-yaml';
 27	
 28	import { resolvePartials } from '../engine/partials.js';
 29	import { resolveConditionals } from '../engine/conditionals.js';
 30	import { resolveVariables } from '../engine/variables.js';
 31	import {
 32	  collapseBlankLines,
 33	  ensureBlankLineBeforeHeadings,
 34	  normalizeNewlines,
 35	} from '../engine/postProcessor.js';
 36	import { serializeTools, serializeToolsList } from '../engine/serializer.js';
 37	import { loadPartials } from '../loaders/partials-loader.js';
 38	import {
 39	  runSuiteInit,
 40	  runBuildContext,
 41	  runPostRender,
 42	  runValidate,
 43	} from '../plugins/runner.js';
 44	
 45	import { resolveFrontmatterTemplate, renderFrontmatter } from './frontmatter.js';
 46	import type { BuildConfig, BuildResult, BuildSummary } from './types.js';
 47	import type { PersonaBuildPlugin, PersonaMetadata, SuiteConfig, TargetType, ValidationResult } from '../plugins/types.js';
 48	import { defaultRegistry } from '../targets/built-in.js';
 49	import type { TargetDefinition } from '../targets/types.js';
 50	import type { TargetRegistry } from '../targets/registry.js';
 51	
 52	// ---------------------------------------------------------------------------
 53	// Internal helpers
 54	// ---------------------------------------------------------------------------
 55	
 56	/**
 57	 * Discover all persona YAML files in the `meta/` subdirectory of a suite.
 58	 *
 59	 * Excludes files whose names start with `_` (shared metadata files such as
 60	 * `_shared.yaml`).  Results are sorted lexicographically.
 61	 *
 62	 * @param suiteConfig  Suite configuration (used to locate `metaSubdir`)
 63	 * @returns            Absolute paths to each persona YAML file, sorted.
 64	 */
 65	async function discoverSuitePersonaYamls(suiteConfig: SuiteConfig): Promise<string[]> {
 66	  const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
 67	  const metaDir = path.join(suiteConfig.srcDir, metaSubdir);
 68	
 69	  const entries = await readdir(metaDir, { withFileTypes: true });
 70	
 71	  return entries
 72	    .filter((e) => e.isFile() && e.name.endsWith('.yaml') && !e.name.startsWith('_'))
 73	    .map((e) => path.join(metaDir, e.name))
 74	    .sort();
 75	}
 76	
 77	/**
 78	 * Load and parse a raw YAML file into a plain object.
 79	 * Used for `_shared.yaml` which does not conform to PersonaMetadata's
 80	 * `name` requirement.
 81	 *
 82	 * @param filePath  Absolute path to the YAML file
 83	 * @returns         Parsed object, or {} when the file is empty/absent
 84	 */
 85	async function loadRawYaml(filePath: string): Promise<Record<string, unknown>> {
 86	  if (!existsSync(filePath)) return {};
 87	  const raw = await readFile(filePath, 'utf8');
 88	  const parsed: unknown = yaml.load(raw);
 89	  if (parsed === null || parsed === undefined) return {};
 90	  if (typeof parsed !== 'object' || Array.isArray(parsed)) return {};
 91	  return parsed as Record<string, unknown>;
 92	}
 93	
 94	/**
 95	 * Load a persona YAML file and return it as a plain metadata record.
 96	 * The `name` field is derived from the filename stem when absent.
 97	 *
 98	 * @param yamlPath  Absolute path to the persona YAML file
 99	 * @returns         Merged metadata record ready for context building
100	 */

101	async function loadPersonaYaml(yamlPath: string): Promise<Record<string, unknown>> {
102	  const raw = await readFile(yamlPath, 'utf8');
103	  const parsed: unknown = yaml.load(raw);
104	
105	  if (parsed === null || parsed === undefined || typeof parsed !== 'object' || Array.isArray(parsed)) {
106	    throw new Error(`buildPersona: expected a YAML object in "${yamlPath}"`);
107	  }
108	
109	  const record = parsed as Record<string, unknown>;
110	
111	  // Derive name from filename stem if not present in YAML
112	  if (!record['name']) {
113	    record['name'] = path.basename(yamlPath, '.yaml');
114	  }
115	
116	  return record;
117	}
118	
119	/**
120	 * Resolve the output directory for a given target from a suite configuration.
121	 *
122	 * Resolution order (first match wins):
123	 *   1. `suiteConfig.outputDirs[definition.outputDirKey]` — generic map, takes precedence.
124	 *   2. `suiteConfig.outVscode` — deprecated fallback for the built-in 'vscode' key.
125	 *   3. `suiteConfig.outClaudeCode` — deprecated fallback for the built-in 'claude-code' key.
126	 *
127	 * The lookup key is `definition.outputDirKey` when a registry definition is
128	 * provided, falling back to the raw `target` name for unregistered targets
129	 * (where `outputDirKey` equals the name by convention).
130	 *
131	 * @param target      The build target name.
132	 * @param suiteConfig The suite configuration to resolve from.
133	 * @param definition  Optional registry definition for the target. When present,
134	 *                    `definition.outputDirKey` is used as the output dir map key.
135	 * @returns           Resolved output directory path.
136	 * @throws {Error}    When no output directory is configured for the target.
137	 */
138	function resolveOutputDir(
139	  target: string,
140	  suiteConfig: SuiteConfig,
141	  definition?: TargetDefinition,
142	): string {
143	  // Build a merged map: deprecated named fields provide the base, outputDirs overrides.
144	  const merged: Record<string, string> = {};
145	  if (suiteConfig.outVscode) merged['vscode'] = suiteConfig.outVscode;
146	  if (suiteConfig.outClaudeCode) merged['claude-code'] = suiteConfig.outClaudeCode;
147	  if (suiteConfig.outputDirs) Object.assign(merged, suiteConfig.outputDirs);
148	
149	  // Use outputDirKey from the registry definition when available, falling back
150	  // to the target name for unregistered targets where outputDirKey === name.
151	  const lookupKey = definition?.outputDirKey ?? target;
152	  const dir = merged[lookupKey];
153	  if (dir) return dir;
154	
155	  throw new Error(
156	    `buildPersona: no output directory configured for target "${target}". ` +
157	      `Add outputDirs['${lookupKey}'] to the suite config, or, for the built-in ` +
158	      `targets, provide the outVscode / outClaudeCode fields.`,
159	  );
160	}
161	
162	/**
163	 * Pre-scan all suites and build a cross-suite agent name map.
164	 *
165	 * For each persona across all configured suites, creates a context variable:
166	 *   key:   `agent_` + slug (hyphens → underscores)
167	 *   value: `"<name> v<version>"`
168	 *
169	 * Slug is taken from the persona YAML's `slug` field, falling back to the
170	 * filename stem. Version falls back to the suite's `default_version`, then
171	 * to `'0.0.0'`.
172	 *
173	 * @param config  Top-level BuildConfig with all suite definitions
174	 * @returns       Map of agent variable keys to display strings
175	 */
176	async function buildAgentNameMap(
177	  config: BuildConfig,
178	): Promise<Record<string, string>> {
179	  const agentMap: Record<string, string> = {};
180	
181	  for (const [, suiteConfig] of Object.entries(config.suites)) {
182	    const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
183	    const sharedYamlPath = path.join(suiteConfig.srcDir, metaSubdir, '_shared.yaml');
184	    const sharedMeta = await loadRawYaml(sharedYamlPath);
185	    const defaultVersion =
186	      typeof sharedMeta['default_version'] === 'string'
187	        ? sharedMeta['default_version']
188	        : '0.0.0';
189	
190	    const personaYamls = await discoverSuitePersonaYamls(suiteConfig);
191	
192	    for (const yamlPath of personaYamls) {
193	      const persona = await loadPersonaYaml(yamlPath);
194	
195	      const slug =
196	        typeof persona['slug'] === 'string'
197	          ? persona['slug']
198	          : path.basename(yamlPath, '.yaml');
199	
200	      const name =
201	        typeof persona['name'] === 'string'
202	          ? persona['name']
203	          : slug;
204	
205	      const version =
206	        typeof persona['version'] === 'string'
207	          ? persona['version']
208	          : defaultVersion;
209	
210	      const underscoredSlug = slug.replace(/-/g, '_');
211	      const key = `agent_${underscoredSlug}`;
212	      agentMap[key] = `${name} v${version}`;
213	
214	      const slugKey = `agent_slug_${underscoredSlug}`;
215	      agentMap[slugKey] = slug;
216	    }
217	  }
218	
219	  return agentMap;
220	}
221	
222	/**
223	 * Build the merged template context for a single persona.
224	 *
225	 * Merge order (later values win):
226	 *   1. configVariables (lowest priority — global BuildConfig.variables)
227	 *   2. suiteVariables  (suite-level SuiteConfig.variables)
228	 *   3. sharedMeta      (parsed _shared.yaml fields)
229	 *   4. personaMeta     (per-persona YAML fields)
230	 *   5. derived/computed fields (version fallback, tools serialisation, etc.)
231	 *   6. agentMap entries (only for keys not already present)
232	 *   7. target flags    (injected last; always win)
233	 *
234	 * @param personaMeta      Per-persona YAML as a plain record
235	 * @param sharedMeta       Parsed `_shared.yaml` fields
236	 * @param agentMap         Cross-suite agent name map (injected by build())
237	 * @param target           The current build target (forwarded to plugins)
238	 * @param registry         Target registry for context-flag injection
239	 * @param configVariables  Optional global variables from BuildConfig.variables
240	 *                         (lowest precedence; overridden by all other layers)
241	 * @param suiteVariables   Optional suite-level variables from SuiteConfig.variables
242	 *                         (overrides configVariables; overridden by sharedMeta and personaMeta)
243	 * @returns                Merged rendering context
244	 */
245	function buildContext(
246	  personaMeta: Record<string, unknown>,
247	  sharedMeta: Record<string, unknown>,
248	  agentMap: Record<string, string> = {},
249	  target?: TargetType,
250	  registry?: TargetRegistry,
251	  configVariables?: Record<string, unknown>,
252	  suiteVariables?: Record<string, unknown>,
253	): Record<string, unknown> {
254	  const version =
255	    typeof personaMeta['version'] === 'string'
256	      ? personaMeta['version']
257	      : typeof sharedMeta['default_version'] === 'string'
258	        ? sharedMeta['default_version']
259	        : '0.0.0';
260	
261	  // Merge base: configVariables first (lowest priority), then suiteVariables,
262	  // then sharedMeta, then personaMeta (highest priority among YAML sources).
263	  const merged: Record<string, unknown> = {
264	    ...(configVariables ?? {}),
265	    ...(suiteVariables ?? {}),
266	    ...sharedMeta,
267	    ...personaMeta,
268	    version,
269	  };
270	
271	  // ── Derived convenience fields (only set when not already provided) ───────
272	  // tools_list / tools_json — serialized from the `tools` array if present
273	  const tools = Array.isArray(merged['tools']) ? (merged['tools'] as string[]) : [];
274	  if (!('tools_list' in merged)) {
275	    merged['tools_list'] = serializeToolsList(tools);
276	  }
277	  if (!('tools_json' in merged)) {
278	    merged['tools_json'] = serializeTools(tools);
279	  }
280	
281	  // cc_tools_list / cc_tools_json — from `cc_tools` or fall back to `tools`
282	  const ccTools = Array.isArray(merged['cc_tools']) ? (merged['cc_tools'] as string[]) : tools;
283	  if (!('cc_tools_list' in merged)) {
284	    merged['cc_tools_list'] = serializeToolsList(ccTools);
285	  }
286	  if (!('cc_tools_json' in merged)) {
287	    merged['cc_tools_json'] = serializeTools(ccTools);
288	  }
289	
290	  // cc_file_name_stem — stem of cc_file_name (for default CC frontmatter template)
291	  if (!('cc_file_name_stem' in merged) && typeof merged['cc_file_name'] === 'string') {
292	    const ccFileName = merged['cc_file_name'] as string;
293	    merged['cc_file_name_stem'] = ccFileName.replace(/\.md$/, '');
294	  }
295	
296	  // da_file_name_stem — stem of da_file_name (for deep-agents output)
297	  if (!('da_file_name_stem' in merged) && typeof merged['da_file_name'] === 'string') {
298	    const daFileName = merged['da_file_name'] as string;
299	    merged['da_file_name_stem'] = daFileName.replace(/\.md$/, '');
300	  }

301	
302	  // da_tools_list / da_tools_json — from `da_tools` or fall back to `tools`
303	  // Intentionally gated on da_file_name: unlike cc_tools_list/cc_tools_json (always emitted for
304	  // every persona), da_* fields are absent when the persona has no deep-agents output file (AC-4).
305	  if (typeof merged['da_file_name'] === 'string') {
306	    const daTools = Array.isArray(merged['da_tools']) ? (merged['da_tools'] as string[]) : tools;
307	    if (!('da_tools_list' in merged)) {
308	      merged['da_tools_list'] = serializeToolsList(daTools);
